// Small independent boot controller. It works before Three.js or any model is downloaded.
const overlay=document.querySelector('#loading'),label=document.querySelector('#load-text'),bar=document.querySelector('#progress'),recovery=document.querySelector('#load-recovery');let completed=false,failed=false,lastProgress=0;
const guard=setTimeout(()=>fail('Loading is taking longer than expected. Try the lightweight view again, or open the moodboards.'),35000);
function fail(message){if(failed)return;failed=true;clearTimeout(guard);overlay.hidden=false;overlay.style.display='flex';overlay.setAttribute('aria-busy','false');label.textContent=message;recovery.hidden=false;document.body.classList.add('load-failed');}
window.villaBoot={progress(message,value){if(failed||completed)return;lastProgress=Math.max(lastProgress,value);label.textContent=message+' · '+Math.round(lastProgress*100)+'%';bar.style.width=Math.round(lastProgress*100)+'%';},ready(){completed=true;clearTimeout(guard);overlay.style.display='none';document.body.classList.remove('load-failed');},fail};
document.querySelector('#retry-3d').onclick=()=>{const url=new URL(location.href);url.searchParams.set('quality','lite');location.href=url.href;};
document.querySelectorAll('[data-board]').forEach(button=>button.addEventListener('click',()=>{if(!failed)return;document.querySelector('#board-image').src='assets/exterior/'+({earth:'mediterranean',chalk:'concrete',canopy:'tropical'}[button.dataset.board]||'mediterranean')+'-board.jpg';}));
document.querySelector('#preview-boards').onclick=()=>{const dialog=document.querySelector('#design-dialog');document.querySelector('#board-image').src='assets/exterior/mediterranean-board.jpg';dialog.showModal();document.querySelector('#close-design').onclick=()=>dialog.close();};
if(!('WebAssembly'in window)||!('WebGL2RenderingContext'in window))fail('This browser can show the villa previews and moodboards. Use a browser with WebGL 2 for the interactive model.');
else requestAnimationFrame(()=>requestAnimationFrame(()=>import('./app.js?v=native-5').catch(()=>fail('The interactive viewer could not start. You can retry or view the moodboards below.'))));
